// Bakes the engine's explosion flipbooks: procedural fire and smoke sheets (8 x 8 frames of 128 x 128)
// each with a motion-vector sheet, from noise carried along a known flow. Everything is generated by
// this script (no source images), so the sheets are the engine's own and CC0.
//
//   node tools/fx/bake-flipbooks.mjs <out dir>        writes fire.png fire_mv.png smoke.png smoke_mv.png
//
// Sheets: frame f sits at column f % 8, row floor(f / 8), row 0 at the top (the GPUParticles3D
// hframes / vframes order). Colour sheets are straight (not premultiplied) RGBA. Motion sheets store,
// in red and green, the flow's motion between this frame and the next in image units (x right, y
// down) as 0.5 + 0.5 * motion / MV_MAX per frame step; MV_MAX is 0.12 of a frame's width (the
// GPUParticles3D `motion_strength` 1). The next frame was baked by carrying the same noise along the
// same flow, so blending frames along these vectors gives the in-between pictures.
import { mkdirSync } from 'node:fs';
import { join } from 'node:path';
import { writePng } from '../lib/png.mjs';

const N = 8, F = 128, FRAMES = N * N, MV_MAX = 0.12;
const out = process.argv[2];
if (!out) { console.error('usage: bake-flipbooks.mjs <out dir>'); process.exit(2); }
mkdirSync(out, { recursive: true });

const hash = (x, y, s) => { let h = (Math.imul(x, 374761393) + Math.imul(y, 668265263) + Math.imul(s, 2246822519)) | 0; h = Math.imul(h ^ (h >>> 13), 1274126177); return ((h ^ (h >>> 16)) >>> 0) / 4294967296; };
const sm = (t) => t * t * (3 - 2 * t);
function vnoise(x, y, s) {
  const xi = Math.floor(x), yi = Math.floor(y), fx = sm(x - xi), fy = sm(y - yi);
  const a = hash(xi, yi, s), b = hash(xi + 1, yi, s), c = hash(xi, yi + 1, s), d = hash(xi + 1, yi + 1, s);
  return a + (b - a) * fx + (c - a) * fy + (a - b - c + d) * fx * fy;
}
const fbm = (x, y, s, oct = 5) => { let v = 0, a = 0.5, f = 1; for (let i = 0; i < oct; i++) { v += a * vnoise(x * f, y * f, s + i); f *= 2.03; a *= 0.5; } return v / 0.96875; };
const clamp = (v, a = 0, b = 1) => Math.min(b, Math.max(a, v));
const smooth = (e0, e1, x) => sm(clamp((x - e0) / (e1 - e0)));

// the flow, image units per whole animation (x right, y down): a billow that spreads, rises and curls
function flow(qx, qy, u, kind) {
  const cx = 0.5, cy = 0.62;
  const spread = kind === 'fire' ? 0.55 : 0.4, rise = kind === 'fire' ? 0.42 : 0.3;
  const ease = 1 - u * 0.6;
  const cxv = (fbm(qx * 3 + 11, qy * 3 + 5, 90, 3) - 0.5) * 0.35, cyv = (fbm(qx * 3 + 31, qy * 3 + 17, 91, 3) - 0.5) * 0.35;
  return [((qx - cx) * spread + cxv) * ease, ((qy - cy) * spread * 0.6 - rise + cyv) * ease];
}

function density(qx, qy, u, kind) {
  // trace this pixel back along the flow to where its noise came from
  const [vx, vy] = flow(qx, qy, u, kind);
  const px = qx - vx * u * 1.0, py = qy - vy * u * 1.0;
  const n = fbm(px * 5.2 + 7, py * 5.2 + 3, kind === 'fire' ? 3 : 8);
  const n2 = fbm(px * 11 + 2, py * 11 + 9, 20, 3);
  const cx = 0.5, cy = 0.62 - 0.16 * Math.sqrt(u);
  const R = (kind === 'fire' ? 0.13 : 0.15) + (kind === 'fire' ? 0.2 : 0.22) * Math.sqrt(u);
  const dx = (qx - cx) / (1.0 + 0.2 * u), dy = (qy - cy) / (1.25 + 0.6 * u);
  const env = 1 - Math.hypot(dx, dy) / R;
  const life = kind === 'fire' ? 1 - smooth(0.5, 1.0, u) : 1 - smooth(0.7, 1.0, u);
  const edge = smooth(0.0, 0.08, Math.min(qx, 1 - qx, qy, 1 - qy));
  let d;
  if (kind === 'fire') d = clamp((env + (n - 0.5) * 1.1 + (n2 - 0.5) * 0.35) * 1.7) * life;
  else d = clamp((env * 0.95 + (n - 0.5) * 1.0 + (n2 - 0.5) * 0.4) * 1.15) * life * (0.55 + 0.45 * Math.min(1, u * 6));
  return d * edge;
}

const ramp = [[0, [0.06, 0.02, 0.01]], [0.18, [0.55, 0.08, 0.02]], [0.4, [0.95, 0.3, 0.04]], [0.65, [1, 0.7, 0.18]], [0.85, [1, 0.93, 0.62]], [1, [1, 1, 1]]];
function fireColor(t) {
  t = clamp(t);
  for (let i = 1; i < ramp.length; i++) if (t <= ramp[i][0]) {
    const [t0, c0] = ramp[i - 1], [t1, c1] = ramp[i], k = (t - t0) / (t1 - t0);
    return [c0[0] + (c1[0] - c0[0]) * k, c0[1] + (c1[1] - c0[1]) * k, c0[2] + (c1[2] - c0[2]) * k];
  }
  return ramp[ramp.length - 1][1];
}

for (const kind of ['fire', 'smoke']) {
  const W = N * F;
  const col = new Uint8Array(W * W * 4), mv = new Uint8Array(W * W * 4);
  for (let f = 0; f < FRAMES; f++) {
    const u = f / (FRAMES - 1), ox = (f % N) * F, oy = Math.floor(f / N) * F;
    const dens = new Float32Array(F * F);
    for (let y = 0; y < F; y++) for (let x = 0; x < F; x++) dens[y * F + x] = density((x + 0.5) / F, (y + 0.5) / F, u, kind);
    for (let y = 0; y < F; y++) for (let x = 0; x < F; x++) {
      const d = dens[y * F + x], qx = (x + 0.5) / F, qy = (y + 0.5) / F;
      const dl = dens[y * F + Math.max(0, x - 1)], dr = dens[y * F + Math.min(F - 1, x + 1)], du = dens[Math.max(0, y - 1) * F + x], dd = dens[Math.min(F - 1, y + 1) * F + x];
      let r, g, b, a;
      if (kind === 'fire') {
        const heat = clamp(d * (0.78 - 0.45 * u) + 0.08 * fbm(qx * 14, qy * 14, 60, 2));
        [r, g, b] = fireColor(heat);
        a = smooth(0.03, 0.45, d);
      } else {
        // soft lighting from the upper left on the density's slope, darker at the bottom of the puff
        const nx = (dl - dr) * 3.0, ny = (du - dd) * 3.0;
        const lit = clamp(0.5 + 0.5 * (nx * -0.6 + ny * -0.8) + 0.5 * d * (0.62 - qy));
        const base = (0.14 + 0.5 * lit) * (0.82 + 0.36 * fbm(qx * 9, qy * 9, 40, 3)) * (d > 0.01 ? 1 : 0.35);
        r = base * 1.0; g = base * 0.98; b = base * 0.96;
        a = clamp(Math.pow(d, 1.15) * 0.95);
      }
      const i = ((oy + y) * W + ox + x) * 4;
      col[i] = Math.round(clamp(r) * 255); col[i + 1] = Math.round(clamp(g) * 255); col[i + 2] = Math.round(clamp(b) * 255); col[i + 3] = Math.round(clamp(a) * 255);
      const [vx, vy] = flow(qx, qy, u, kind), s = 1 / (FRAMES - 1) / 1.0;
      mv[i] = Math.round(clamp(0.5 + 0.5 * (vx * s) / MV_MAX) * 255);
      mv[i + 1] = Math.round(clamp(0.5 + 0.5 * (vy * s) / MV_MAX) * 255);
      mv[i + 2] = 128; mv[i + 3] = 255;
    }
  }
  writePng(join(out, `${kind}.png`), W, W, col);
  writePng(join(out, `${kind}_mv.png`), W, W, mv);
  console.log(`${kind}.png, ${kind}_mv.png (${W}x${W}, ${FRAMES} frames)`);
}

// scorch marks: four irregular blast marks (2 x 2 of 256 pixels) for Explosion3D's decals: a dark, ragged
// core with streaks thrown outward, alpha fading to nothing at the edge. Different shapes, so a yard of
// scorch marks does not repeat (the decal also turns and stretches each one).
{
  const S = 512, C = 256, col = new Uint8Array(S * S * 4);
  for (let v = 0; v < 4; v++) {
    const ox = (v % 2) * C, oy = Math.floor(v / 2) * C;
    const rays = 7 + v * 2, seed = 100 + v * 17;
    for (let y = 0; y < C; y++) for (let x = 0; x < C; x++) {
      const qx = (x + 0.5) / C * 2 - 1, qy = (y + 0.5) / C * 2 - 1, r = Math.hypot(qx, qy), a = Math.atan2(qy, qx);
      const warp = fbm(Math.cos(a) * 1.7 + 5 + v * 3, Math.sin(a) * 1.7 + 9, seed, 3);
      const ray = Math.pow(Math.abs(Math.sin(a * rays * 0.5 + warp * 6)), 6) * fbm(a * 2 + v, 1.3, seed + 1, 2);
      const edge = 0.45 + 0.35 * warp + 0.25 * ray;
      const grit = fbm(qx * 7 + v, qy * 7, seed + 2, 4);
      let m = 1 - smooth(edge * 0.55, edge * 1.05, r);
      m *= 0.75 + 0.35 * grit;
      const i = ((oy + y) * S + ox + x) * 4, g = Math.round(clamp(0.3 + 0.7 * (1 - m * 0.85)) * 255);
      col[i] = g; col[i + 1] = g; col[i + 2] = g; col[i + 3] = Math.round(clamp(m * 1.1) * 255);
    }
  }
  writePng(join(out, 'scorch.png'), S, S, col);
  console.log('scorch.png (512x512, 4 variants)');
}
